CREATE OR REPLACE FUNCTION private.pos_cad6_product_is_perishable_blocking(p_product pos_products)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_context_text text;
begin
  if coalesce(p_product.expiration_mode, 'NONE') <> 'SHELF_LIFE' then
    return false;
  end if;

  if private.pos_cad6_truthy(p_product.metadata->>'perishableBlocking')
    or private.pos_cad6_truthy(p_product.metadata->>'perishable_blocking')
    or private.pos_cad6_truthy(p_product.metadata->>'isPerishable')
    or private.pos_cad6_truthy(p_product.metadata->>'is_perishable')
    or private.pos_cad6_truthy(p_product.batch_management->>'perishableBlocking')
    or private.pos_cad6_truthy(p_product.batch_management->>'perishable_blocking') then
    return true;
  end if;

  v_context_text := private.pos_cad6_product_context_text(p_product);
  return private.pos_cad6_text_matches_perishable(v_context_text);
end;
$function$

CREATE OR REPLACE FUNCTION private.rest_inv5_modifier_inventory_quantity(p_modifier jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_has_explicit boolean;
  v_quantity numeric;
begin
  if p_modifier is null or jsonb_typeof(p_modifier) <> 'object' then
    return null;
  end if;

  v_has_explicit := (p_modifier ? 'ingredientQuantity') or (p_modifier ? 'ingredient_quantity');

  if v_has_explicit then
    v_quantity := private.pos_sale_jsonb_numeric(p_modifier, array['ingredientQuantity','ingredient_quantity'], null);
    if v_quantity is not null and v_quantity > 0 then
      return v_quantity;
    end if;
    return null;
  end if;

  if p_modifier ? 'quantity' then
    v_quantity := private.pos_sale_jsonb_numeric(p_modifier, array['quantity'], null);
    if v_quantity is not null and v_quantity > 0 then
      return v_quantity;
    end if;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.rest_inv5_modifier_tracks_inventory(p_modifier jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_ingredient_id text;
  v_quantity numeric;
begin
  if p_modifier is null or jsonb_typeof(p_modifier) <> 'object' then
    return false;
  end if;

  v_ingredient_id := private.pos_sale_jsonb_text(
    p_modifier,
    array['ingredientId','ingredient_id'],
    null
  );
  v_quantity := private.rest_inv5_modifier_inventory_quantity(p_modifier);

  return v_ingredient_id is not null
    and v_quantity is not null
    and v_quantity > 0;
end;
$function$
